// The DTO decorators need the reflect metadata polyfill (the app loads it in
// main.ts; a bare Jest process has to load it itself).
import 'reflect-metadata';

import { DuffelService } from '../src/modules/duffel/duffel.service';
import { DuffelBookingProvider } from '../src/modules/bookings/adapters/duffel-booking.provider';

/**
 * P3-D5 — the offer-passenger-id lifecycle across the real Duffel boundary.
 *
 * Duffel's order passengers carry the ids generated by the ORIGINAL offer
 * request (`Offer.passenger.id`). They are not TokiGo values and must never be
 * invented. They are recovered from the stored offer id during revalidation,
 * persisted in the booking snapshot, and mapped back onto the collected
 * travellers by (type, ordinal) at confirm time.
 */
class FakeDuffelService {
  providerName = 'Duffel Flight Provider';

  createOrderCalls: Array<{
    offerId: string;
    passengers: Array<Record<string, unknown>>;
    payments: Array<Record<string, unknown>>;
  }> = [];

  revalidateResult: Record<string, unknown> = {
    price: 800,
    currency: 'USD',
    available: true,
    passengers: [
      { id: 'pas_1', type: 'adult', age: null },
      { id: 'pas_2', type: 'adult', age: null },
      { id: 'pas_3', type: 'infant_without_seat', age: 1 },
    ],
    passengerIdentityDocumentsRequired: false,
    supportedPassengerIdentityDocumentTypes: ['passport'],
  };

  async createOrder(
    offerId: string,
    passengers: Array<Record<string, unknown>>,
    payments: Array<Record<string, unknown>>,
  ): Promise<Record<string, unknown>> {
    this.createOrderCalls.push({ offerId, passengers, payments });
    return {
      id: 'ord_1',
      booking_reference: 'ABC123',
      status: 'confirmed',
      total_amount: '800.00',
      total_currency: 'USD',
    };
  }

  async revalidateOffer(offerId: string): Promise<any> {
    return {
      success: true,
      providerId: 'duffel-flight',
      providerName: 'Duffel Flight Provider',
      data: { ...this.revalidateResult, rawId: offerId },
      timestamp: new Date(),
    };
  }
}

function traveler(overrides: Record<string, unknown> = {}): Record<string, unknown> {
  return {
    passengerType: 'adult',
    firstName: 'Nour',
    lastName: 'Adel',
    dateOfBirth: '1990-01-01',
    gender: 'M',
    title: 'mr',
    email: 'nour@example.com',
    phone: '+201000000000',
    documentType: 'PASSPORT',
    documentNumber: 'P123456',
    documentIssueCountry: 'EG',
    documentExpiry: '2030-01-01',
    ...overrides,
  };
}

function snapshot(passengers: Array<Record<string, unknown>>): Record<string, unknown> {
  return {
    offerId: 'off_1',
    duffelPassengers: passengers,
    duffelIdentityDocumentsRequired: false,
    duffelSupportedDocumentTypes: ['passport'],
  };
}

const TWO_ADULTS_ONE_INFANT = [
  { id: 'pas_1', type: 'adult', age: null },
  { id: 'pas_2', type: 'adult', age: null },
  { id: 'pas_3', type: 'infant_without_seat', age: 1 },
];

describe('Duffel revalidation — passenger id capture', () => {
  it('surfaces the offer passenger ids through the handoff', async () => {
    const fake = new FakeDuffelService();
    const provider = new DuffelBookingProvider(fake as unknown as DuffelService);

    const result = await provider.revalidateBooking('off_1');

    expect(result.success).toBe(true);
    expect(result.data?.handoff?.duffelPassengers).toEqual([
      { id: 'pas_1', type: 'adult', age: null },
      { id: 'pas_2', type: 'adult', age: null },
      { id: 'pas_3', type: 'infant_without_seat', age: 1 },
    ]);
    expect(result.data?.handoff?.duffelIdentityDocumentsRequired).toBe(false);
  });

  it('keeps the price/availability contract unchanged', async () => {
    const fake = new FakeDuffelService();
    const provider = new DuffelBookingProvider(fake as unknown as DuffelService);

    const result = await provider.revalidateBooking('off_1');

    expect(result.data?.price).toBe(800);
    expect(result.data?.currency).toBe('USD');
    expect(result.data?.available).toBe(true);
  });
});

describe('Duffel createBooking — id mapping by type and ordinal', () => {
  it('maps an infant traveller to the infant offer passenger id', async () => {
    const fake = new FakeDuffelService();
    const provider = new DuffelBookingProvider(fake as unknown as DuffelService);

    const result = await provider.createBooking({
      offerId: 'off_1',
      offerSnapshot: snapshot(TWO_ADULTS_ONE_INFANT),
      travelers: [
        traveler({ firstName: 'Nour' }),
        traveler({ firstName: 'Mona' }),
        traveler({
          firstName: 'Youssef',
          passengerType: 'infant',
          dateOfBirth: '2025-01-01',
          accompanyingAdultIndex: 0,
        }),
      ],
    });

    expect(result.success).toBe(true);
    expect(fake.createOrderCalls[0].passengers.map((p) => p.id)).toEqual([
      'pas_1',
      'pas_2',
      'pas_3',
    ]);
  });

  it('does not reuse an adult id for a child traveller', async () => {
    const fake = new FakeDuffelService();
    const provider = new DuffelBookingProvider(fake as unknown as DuffelService);

    await provider.createBooking({
      offerId: 'off_1',
      offerSnapshot: snapshot([
        { id: 'pas_1', type: 'adult', age: null },
        { id: 'pas_2', type: 'child', age: 7 },
      ]),
      travelers: [
        traveler({ firstName: 'Nour' }),
        traveler({ firstName: 'Youssef', passengerType: 'child' }),
      ],
    });

    expect(fake.createOrderCalls[0].passengers.map((p) => p.id)).toEqual([
      'pas_1',
      'pas_2',
    ]);
  });

  it('blocks when the traveller party does not match the offer party', async () => {
    const fake = new FakeDuffelService();
    const provider = new DuffelBookingProvider(fake as unknown as DuffelService);

    const result = await provider.createBooking({
      offerId: 'off_1',
      offerSnapshot: snapshot(TWO_ADULTS_ONE_INFANT),
      travelers: [
        traveler({ firstName: 'Nour' }),
        traveler({ firstName: 'Mona' }),
      ],
    });

    expect(result.success).toBe(false);
    expect(fake.createOrderCalls).toHaveLength(0);
    expect(result.error).toContain('the offer has 3 passengers but 2 were supplied');
  });

  it('blocks when the traveller party has more members than the offer', async () => {
    const fake = new FakeDuffelService();
    const provider = new DuffelBookingProvider(fake as unknown as DuffelService);

    const result = await provider.createBooking({
      offerId: 'off_1',
      offerSnapshot: snapshot([
        { id: 'pas_1', type: 'adult', age: null },
        { id: 'pas_2', type: 'adult', age: null },
      ]),
      travelers: [
        traveler({ firstName: 'Nour' }),
        traveler({ firstName: 'Mona' }),
        traveler({ firstName: 'Youssef' }),
      ],
    });

    expect(result.success).toBe(false);
    expect(fake.createOrderCalls).toHaveLength(0);
    expect(result.error).toContain('no adult passenger left on the offer');
  });

  it('blocks a traveller with no classification', async () => {
    const fake = new FakeDuffelService();
    const provider = new DuffelBookingProvider(fake as unknown as DuffelService);

    const result = await provider.createBooking({
      offerId: 'off_1',
      offerSnapshot: snapshot(TWO_ADULTS_ONE_INFANT),
      travelers: [traveler({ passengerType: undefined })],
    });

    expect(result.success).toBe(false);
    expect(fake.createOrderCalls).toHaveLength(0);
    expect(result.error).toContain('type');
  });
});

describe('Duffel createBooking — infant relationship', () => {
  it('links the infant to the adult it names', async () => {
    const fake = new FakeDuffelService();
    const provider = new DuffelBookingProvider(fake as unknown as DuffelService);

    const result = await provider.createBooking({
      offerId: 'off_1',
      offerSnapshot: snapshot(TWO_ADULTS_ONE_INFANT),
      travelers: [
        traveler({ firstName: 'Nour' }),
        traveler({ firstName: 'Mona' }),
        traveler({
          firstName: 'Youssef',
          passengerType: 'infant',
          dateOfBirth: '2025-01-01',
          accompanyingAdultIndex: 1,
        }),
      ],
    });

    expect(result.success).toBe(true);
    const passengers = fake.createOrderCalls[0].passengers;
    expect(passengers[0]).not.toHaveProperty('infant_passenger_id');
    expect(passengers[1].infant_passenger_id).toBe('pas_3');
    expect(passengers[2]).not.toHaveProperty('infant_passenger_id');
  });

  it('blocks an infant that does not name its adult', async () => {
    const fake = new FakeDuffelService();
    const provider = new DuffelBookingProvider(fake as unknown as DuffelService);

    const result = await provider.createBooking({
      offerId: 'off_1',
      offerSnapshot: snapshot(TWO_ADULTS_ONE_INFANT),
      travelers: [
        traveler({ firstName: 'Nour' }),
        traveler({ firstName: 'Mona' }),
        traveler({
          firstName: 'Youssef',
          passengerType: 'infant',
          dateOfBirth: '2025-01-01',
        }),
      ],
    });

    expect(result.success).toBe(false);
    expect(fake.createOrderCalls).toHaveLength(0);
    expect(result.error).toContain('accompanying adult');
  });

  it('blocks an infant whose named adult is another child', async () => {
    const fake = new FakeDuffelService();
    const provider = new DuffelBookingProvider(fake as unknown as DuffelService);

    const result = await provider.createBooking({
      offerId: 'off_1',
      offerSnapshot: snapshot([
        { id: 'pas_1', type: 'child', age: 7 },
        { id: 'pas_2', type: 'infant_without_seat', age: 1 },
      ]),
      travelers: [
        traveler({ firstName: 'Youssef', passengerType: 'child' }),
        traveler({
          firstName: 'Salma',
          passengerType: 'infant',
          dateOfBirth: '2025-01-01',
          accompanyingAdultIndex: 0,
        }),
      ],
    });

    expect(result.success).toBe(false);
    expect(fake.createOrderCalls).toHaveLength(0);
    expect(result.error).toContain('accompanying adult');
  });

  it('blocks two infants linked to the same adult', async () => {
    const fake = new FakeDuffelService();
    const provider = new DuffelBookingProvider(fake as unknown as DuffelService);

    const result = await provider.createBooking({
      offerId: 'off_1',
      offerSnapshot: snapshot([
        { id: 'pas_1', type: 'adult', age: null },
        { id: 'pas_2', type: 'infant_without_seat', age: 1 },
        { id: 'pas_3', type: 'infant_without_seat', age: 0 },
      ]),
      travelers: [
        traveler({ firstName: 'Nour' }),
        traveler({
          firstName: 'A',
          passengerType: 'infant',
          dateOfBirth: '2025-01-01',
          accompanyingAdultIndex: 0,
        }),
        traveler({
          firstName: 'B',
          passengerType: 'infant',
          dateOfBirth: '2026-01-01',
          accompanyingAdultIndex: 0,
        }),
      ],
    });

    expect(result.success).toBe(false);
    expect(fake.createOrderCalls).toHaveLength(0);
    expect(result.error).toContain('already has an infant');
  });
});

describe('Duffel createBooking — conditional identity documents', () => {
  it('blocks when the offer requires documents and one is missing', async () => {
    const fake = new FakeDuffelService();
    const provider = new DuffelBookingProvider(fake as unknown as DuffelService);

    const result = await provider.createBooking({
      offerId: 'off_1',
      offerSnapshot: {
        ...snapshot(TWO_ADULTS_ONE_INFANT),
        duffelIdentityDocumentsRequired: true,
      },
      travelers: [traveler({ documentNumber: undefined })],
    });

    expect(result.success).toBe(false);
    expect(fake.createOrderCalls).toHaveLength(0);
    expect(result.error).toContain('identity_documents');
  });

  it('blocks a document type the offer does not support', async () => {
    const fake = new FakeDuffelService();
    const provider = new DuffelBookingProvider(fake as unknown as DuffelService);

    const result = await provider.createBooking({
      offerId: 'off_1',
      offerSnapshot: {
        ...snapshot(TWO_ADULTS_ONE_INFANT),
        duffelIdentityDocumentsRequired: true,
        duffelSupportedDocumentTypes: ['known_traveler_number'],
      },
      travelers: [traveler({ documentType: 'PASSPORT' })],
    });

    expect(result.success).toBe(false);
    expect(fake.createOrderCalls).toHaveLength(0);
    expect(result.error).toContain('identity_documents');
  });

  it('sends the document when the offer supports it', async () => {
    const fake = new FakeDuffelService();
    const provider = new DuffelBookingProvider(fake as unknown as DuffelService);

    const result = await provider.createBooking({
      offerId: 'off_1',
      offerSnapshot: snapshot([{ id: 'pas_1', type: 'adult', age: null }]),
      travelers: [traveler()],
    });

    expect(result.success).toBe(true);
    expect(fake.createOrderCalls[0].passengers[0].identity_documents).toEqual([
      {
        type: 'passport',
        unique_identifier: 'P123456',
        issuing_country_code: 'EG',
        expires_on: '2030-01-01',
      },
    ]);
  });
});
